groundcover:index/connectedApp:Connected.description:
Connected App resource for managing integrations with external services.

## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as groundcover from "@groundcover-com/groundcover";

const config = new pulumi.Config();
const groundcoverApiKey = config.require("groundcoverApiKey");
const groundcoverBackendId = config.require("groundcoverBackendId");
const slackWebhookUrl = config.require("slackWebhookUrl");
const pagerdutyRoutingKey = config.require("pagerdutyRoutingKey");
const slack = new groundcover.ConnectedApp("slack", {
    type: "slack-webhook",
    data: {
        url: slackWebhookUrl,
    },
});
const pagerduty = new groundcover.ConnectedApp("pagerduty", {
    type: "pagerduty",
    data: {
        routingKey: pagerdutyRoutingKey,
    },
});
const pagerdutyWithSeverity = new groundcover.ConnectedApp("pagerdutyWithSeverity", {
    type: "pagerduty",
    data: {
        routingKey: pagerdutyRoutingKey,
        severityMapping: {
            critical: "critical",
            error: "error",
            warning: "warning",
            info: "info",
        },
    },
});
export const slackAppId = slack.id;
export const pagerdutyAppId = pagerduty.id;
```
