```typescript
import * as pulumi from "@pulumi/pulumi";
import * as groundcover from "@groundcover-com/groundcover";

const config = new pulumi.Config();
const groundcoverApiKey = config.require("groundcoverApiKey");
const groundcoverBackendId = config.require("groundcoverBackendId");
const slackWebhookUrl = config.require("slackWebhookUrl");
const pagerdutyRoutingKey = config.require("pagerdutyRoutingKey");
const slack = new groundcover.ConnectedApp("slack", {
    type: "slack-webhook",
    data: {
        url: slackWebhookUrl,
    },
});
const pagerduty = new groundcover.ConnectedApp("pagerduty", {
    type: "pagerduty",
    data: {
        routingKey: pagerdutyRoutingKey,
    },
});
const criticalAlerts = new groundcover.NotificationRoute("criticalAlerts", {
    query: "severity:critical",
    routes: [
        {
            status: ["Alerting"],
            connected_apps: [
                {
                    type: "pagerduty",
                    id: pagerduty.id,
                },
                {
                    type: "slack-webhook",
                    id: slack.id,
                },
            ],
        },
        {
            status: ["Resolved"],
            connected_apps: [{
                type: "slack-webhook",
                id: slack.id,
            }],
        },
    ],
    notificationSettings: {
        renotification_interval: "1h",
    },
});
const allAlertsToSlack = new groundcover.NotificationRoute("allAlertsToSlack", {
    query: "*",
    routes: [{
        status: [
            "Alerting",
            "Resolved",
        ],
        connected_apps: [{
            type: "slack-webhook",
            id: slack.id,
        }],
    }],
    notificationSettings: {
        renotification_interval: "30m",
    },
});
export const criticalRouteId = criticalAlerts.id;
export const allAlertsRouteId = allAlertsToSlack.id;
