groundcover:index/syntheticTest:Syntheti.description:
Manages a groundcover Synthetic Test. Synthetic tests allow you to proactively monitor your services by running periodic HTTP checks against specified endpoints.

## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as groundcover from "@groundcover-com/groundcover";

// Example: Simple HTTP health check
const httpHealthCheck = new groundcover.SyntheticTest("httpHealthCheck", {
    interval: "1m",
    httpCheck: [{
        url: "https://httpbin.org/status/200",
        method: "GET",
        timeout: "10s",
    }],
    assertions: [
        {
            source: "statusCode",
            operator: "eq",
            target: "200",
        },
        {
            source: "responseTime",
            operator: "lt",
            target: "5000",
        },
    ],
    retry: [{
        count: 2,
        interval: "1s",
    }],
});
// Example: HTTP POST with body and headers
const httpPostCheck = new groundcover.SyntheticTest("httpPostCheck", {
    interval: "5m",
    httpCheck: [{
        url: "https://httpbin.org/post",
        method: "POST",
        timeout: "10s",
        headers: {
            "Content-Type": "application/json",
        },
        body: [{
            type: "json",
            content: "{\"test\": \"data\"}",
        }],
    }],
    assertions: [{
        source: "statusCode",
        operator: "eq",
        target: "200",
    }],
});
// Example: Authenticated HTTP check using secrets
const authenticatedCheck = new groundcover.SyntheticTest("authenticatedCheck", {
    interval: "5m",
    httpCheck: [{
        url: "https://api.example.com/health",
        method: "GET",
        timeout: "10s",
        auth: [{
            type: "bearer",
            token: "secretRef::store::your-secret-id",
        }],
    }],
    assertions: [{
        source: "statusCode",
        operator: "eq",
        target: "200",
    }],
});
// Example: With custom labels and severity
const performanceCheck = new groundcover.SyntheticTest("performanceCheck", {
    interval: "30s",
    labels: {
        env: "production",
        team: "platform",
    },
    httpCheck: [{
        url: "https://api.example.com/status",
        method: "GET",
        timeout: "5s",
    }],
    assertions: [
        {
            source: "statusCode",
            operator: "eq",
            target: "200",
            severity: "critical",
        },
        {
            source: "responseTime",
            operator: "lt",
            target: "300",
            severity: "degraded",
        },
    ],
    retry: [{
        count: 3,
        interval: "500ms",
    }],
});
export const httpHealthCheckId = httpHealthCheck.id;
export const httpPostCheckId = httpPostCheck.id;
